import asyncio
from crawl4ai import AsyncWebCrawler

async def main():
    async with AsyncWebCrawler(verbose=True) as crawler:
        result = await crawler.arun(url="https://www.google.com/search?q=trending+news+on+AI&sca_esv=39810f5665557e26&sxsrf=ADLYWIJJhXHjwO0svAwU7WhD50qxZILnEQ%3A1736142729880&ei=iW97Z_uyNZTH4-EPmpGmyAg&ved=0ahUKEwi7m8bVs-CKAxWU4zgGHZqICYkQ4dUDCBA&uact=5&oq=trending+news+on+AI&gs_&sclient=gws-wiz-serp")
        print(result.markdown)

if __name__ == "__main__":
    asyncio.run(main())